package com.realsneed.biblereader.data

import android.content.res.AssetManager
import java.io.IOException

/**
 * English definitions from **Webster's 1828 American Dictionary of the English
 * Language** - the dictionary that was written to be read alongside this Bible,
 * defining `conversation` as "general course of manners; behavior", `prevent` as
 * "to go before", and quoting the KJV in its own examples.
 *
 * The asset is generated by `tools/build_webster.py` and is **keyed by the KJV's
 * own word forms**, not by dictionary headwords: the archaic forms (`hath`,
 * `spake`, `beginneth`) and every inflection are already resolved during the
 * build, so a lookup here is a plain map hit. Nothing is guessed on the device.
 *
 * It holds 8,559 entries - every word of the KJV the 1828 dictionary can define,
 * which is 95.5% of its 789,628 words. What is left is almost entirely proper
 * names (Israel, David, Jerusalem), which no dictionary defines; the Hebrew and
 * Greek lexicon covers those.
 *
 * Licensed CC BY-SA 4.0; see `assets/usfm/kjv/webster.LICENSE`.
 */
class WebsterRepository(private val assets: AssetManager) {

    private val lock = Any()
    private var entries: HashMap<String, String>? = null

    /** Reads the dictionary ahead of time. Call this from a background thread. */
    fun warmUp() {
        load()
    }

    /** The 1828 definition of [word], or null if the dictionary has none. */
    fun definition(word: String): String? = load()[key(word)]

    private fun load(): HashMap<String, String> {
        synchronized(lock) { entries?.let { return it } }
        val map = HashMap<String, String>(ENTRIES)
        try {
            assets.open("$ASSET_DIR/$ASSET_NAME").bufferedReader().use { reader ->
                while (true) {
                    val line = reader.readLine() ?: break
                    val tab = line.indexOf('\t')
                    if (tab <= 0) continue
                    // One entry per line, so paragraphs are stored as unit
                    // separators; the card shows them as line breaks.
                    map[line.substring(0, tab)] = line.substring(tab + 1).replace(PARAGRAPH, '\n')
                }
            }
        } catch (e: IOException) {
            // No dictionary: definitions simply have nothing to add.
        }
        synchronized(lock) { entries = map }
        return map
    }

    companion object {
        private const val ASSET_DIR = StrongsRepository.ASSET_DIR
        private const val ASSET_NAME = "webster"
        private const val ENTRIES = 8559

        /** Paragraph break inside an entry - see tools/build_webster.py. */
        private const val PARAGRAPH = '\u001F'

        /** The letters a word form keeps - the same rule the asset was built with. */
        private fun key(word: String): String {
            val out = StringBuilder(word.length)
            for (c in word) {
                when {
                    c in 'a'..'z' || c in '0'..'9' || c == '\'' || c == '-' -> out.append(c)
                    c in 'A'..'Z' -> out.append(c.lowercaseChar())
                }
            }
            return out.toString()
        }

        @Volatile
        private var instance: WebsterRepository? = null

        fun get(assets: AssetManager): WebsterRepository =
            instance ?: synchronized(this) {
                instance ?: WebsterRepository(assets).also { instance = it }
            }
    }
}
